const cmds = [
  ["launch", "sed -n '1,240p' examples/search-r1/run_qwen2.5_3B.sh"],
  ["gen", "sed -n '1,280p' examples/search-r1/generate_with_search.py"],
  ["reward", "sed -n '1,280p' examples/search-r1/qa_em_format.py"],
  ["hist_scores", "cat historical_evidence/eval_scores.json && printf '\\n--- manifest ---\\n' && cat historical_evidence/manifest.json && printf '\\n--- README ---\\n' && cat historical_evidence/README.txt"],
  ["hist_excerpt", "sed -n '1,260p' historical_evidence/log_excerpt.txt"],
  ["metrics", "cat outputs/metrics.json && printf '\\n--- trace ---\\n' && sed -n '1,300p' outputs/historical_eval_trace.log"],
  ["logs", "sed -n '1,260p' experiment_logs/cybertron-751761.log; printf '\\n--- stderr ---\\n'; sed -n '1,260p' experiment_logs/cybertron-751761.stderr.log"],
  ["scripts", "sed -n '1,240p' scripts/models/qwen2.5-3B.sh; printf '\\n--- pyproject ---\\n'; sed -n '1,220p' pyproject.toml"],
  ["find_configs", "find . -maxdepth 5 -type f \\( -name '*.yaml' -o -name '*.yml' -o -name '*.json' -o -name '*.sh' \\) | sort | head -300"]
];
const rs = await Promise.all(cmds.map(async ([name,cmd]) => [name, await tools.exec_command({cmd,workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000})]));
for (const [name,r] of rs) { text(`===== ${name} =====\n${r.output}`); }

