arguments.input:
const cmds = [
 ["outputfiles","find wandb -type f -maxdepth 5 -printf '%p %s\\n' | sort | head -100"],
 ["out_head","find wandb -type f -name output.log -print -exec sh -c 'echo ==== \"$1\"; sed -n \"1,160p\" \"$1\"' sh {} \\;"],
 ["out_grep","find wandb -type f -name output.log -print -exec sh -c 'echo ==== \"$1\"; grep -n -E \"rollout [0-9]+:|perf [0-9]+:|eval [0-9]+:|loss|grad|entropy|kl|raw_reward|reward|truncated|response_len\" \"$1\" | head -120' sh {} \\;"],
 ["out_tail","find wandb -type f -name output.log -print -exec sh -c 'echo ==== \"$1\"; tail -160 \"$1\"' sh {} \\;"],
 ["wandb_history","find wandb -type f -printf '%p\\n' | grep -E 'history|wandb' | head -100"],
 ["receipts","find outputs -maxdepth 2 -type f -printf '%p %s\\n'; for p in outputs/*.json; do echo ==== $p; cat \"$p\"; done"]
];
const rs = await Promise.all(cmds.map(async ([name,cmd]) => [name,await tools.exec_command({cmd,workdir:"/workspace",yield_time_ms:10000,max_output_tokens:40000})]));
for (const [name,r] of rs) text(`===== ${name} =====\n${r.output}`);

