import ast,re
from pathlib import Path
p=Path('wandb/latest-run/files/output.log')
E=[]; R=[]; P=[]
for line in p.read_text(errors='replace').splitlines():
 m=re.search(r' - eval (\d+): (\{.*\})$',line)
 if m:
  d=ast.literal_eval(m.group(2)); E.append((int(m.group(1)),d.get('eval/nq_test'),d.get('eval/nq_test/response_len/mean')))
 m=re.search(r' - perf (\d+): (\{.*\})$',line)
 if m:
  d=ast.literal_eval(m.group(2)); P.append((int(m.group(1)),d.get('rollout/response_len/mean'),d.get('rollout/truncated_ratio')))
 m=re.search(r' - rollout (\d+): (\{.*\})$',line)
 if m:
  d=ast.literal_eval(m.group(2)); R.append((int(m.group(1)),d.get('rollout/raw_reward'),d.get('rollout/rewards')))
print('step eval raw response')
for i in range(0,min(len(E),len(R))):
 print(E[i][0], E[i][1], R[i][1], R[i][2], E[i][2], P[i][1],P[i][2])
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:20000});
