const cmds = [
 ["report", "cat /workspace/report.md"],
 ["hist_eval", "cat /workspace/historical_evidence/eval_scores.json"],
 ["hist_excerpt", "cat /workspace/historical_evidence/log_excerpt.txt"],
 ["metrics", "cat /workspace/outputs/metrics.json"],
 ["trace", "cat /workspace/outputs/historical_eval_trace.log"],
 ["reward", "nl -ba /workspace/examples/search-r1/generate_with_search.py | sed -n '1,420p'; printf '\\n--- QA ---\\n'; nl -ba /workspace/examples/search-r1/qa_em_format.py | sed -n '1,300p'"],
 ["modelargs", "cat /workspace/scripts/models/qwen2.5-3B.sh"],
 ["startretriever", "cat /workspace/examples/search-r1/start_retriver.sh"],
 ["files", "find /workspace/experiment_logs /workspace/wandb /workspace/outputs /workspace/historical_evidence -maxdepth 3 -type f -printf '%p %s bytes\\n' | sort"]
];
const rs = await Promise.all(cmds.map(async ([n,cmd]) => [n, await tools.exec_command({cmd,workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000})]));
for (const [n,r] of rs) text(`===== ${n} =====\n${r.output}`);

